import React, { useState, useEffect } from 'react';
import { useSearchParams } from 'react-router-dom';
import { Search, Loader2, AlertCircle } from 'lucide-react';
import { formatDistanceToNow } from 'date-fns';
import { zhCN } from 'date-fns/locale';

const SearchPage = () => {
  const [searchParams, setSearchParams] = useSearchParams();
  const [query, setQuery] = useState(searchParams.get('q') || '');
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [hasSearched, setHasSearched] = useState(false);

  const performSearch = async (searchQuery, page = 1) => {
    if (!searchQuery.trim()) return;

    try {
      setLoading(true);
      setError(null);

      const params = new URLSearchParams({
        q: searchQuery,
        page: page.toString(),
        limit: '10'
      });

      const response = await fetch(`/api/news/search?${params}`);
      const data = await response.json();

      if (data.success) {
        setResults(data.data.data || []);
      } else {
        throw new Error(data.error || '搜索失败');
      }
    } catch (err) {
      console.error('搜索失败:', err);
      setError(err.message);
    } finally {
      setLoading(false);
      setHasSearched(true);
    }
  };

  const handleSearch = (e) => {
    e.preventDefault();
    if (query.trim()) {
      setSearchParams({ q: query.trim() });
      performSearch(query.trim());
    }
  };

  useEffect(() => {
    const queryParam = searchParams.get('q');
    if (queryParam) {
      setQuery(queryParam);
      performSearch(queryParam);
    }
  }, [searchParams]);

  const getCategoryColor = (category) => {
    const colors = {
      'AI新闻': 'bg-blue-100 text-blue-700',
      'AI框架': 'bg-green-100 text-green-700',
      '新算法': 'bg-purple-100 text-purple-700',
      '新思路': 'bg-yellow-100 text-yellow-700',
      '新工具': 'bg-pink-100 text-pink-700',
    };
    return colors[category] || 'bg-gray-100 text-gray-700';
  };

  const highlightText = (text, searchTerm) => {
    if (!searchTerm) return text;

    const regex = new RegExp(`(${searchTerm})`, 'gi');
    const parts = text.split(regex);

    return parts.map((part, index) => 
      regex.test(part) ? (
        <mark key={index} className="bg-yellow-200 px-1 rounded">
          {part}
        </mark>
      ) : part
    );
  };

  return (
    <div className="max-w-4xl mx-auto">
      {/* 页面标题 */}
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-gray-900 mb-2">搜索AI资讯</h1>
        <p className="text-gray-600">搜索AI相关的新闻、算法、框架、工具和思路</p>
      </div>

      {/* 搜索表单 */}
      <form onSubmit={handleSearch} className="mb-8">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
          <input
            type="text"
            placeholder="输入关键词搜索AI资讯..."
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none text-lg"
          />
          <button
            type="submit"
            disabled={loading || !query.trim()}
            className="absolute right-2 top-1/2 transform -translate-y-1/2 px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
          >
            {loading ? (
              <Loader2 className="w-4 h-4 animate-spin" />
            ) : (
              '搜索'
            )}
          </button>
        </div>
      </form>

      {/* 搜索结果 */}
      {hasSearched && (
        <div className="mb-6">
          <h2 className="text-lg font-semibold text-gray-900">
            搜索结果
            {query && ` - "${query}"`}
          </h2>
        </div>
      )}

      {/* 加载状态 */}
      {loading && (
        <div className="flex items-center justify-center py-12">
          <Loader2 className="w-8 h-8 animate-spin text-blue-600 mr-2" />
          <span className="text-gray-600">搜索中...</span>
        </div>
      )}

      {/* 错误状态 */}
      {error && !loading && (
        <div className="text-center py-12">
          <AlertCircle className="w-12 h-12 text-red-500 mx-auto mb-4" />
          <h3 className="text-lg font-medium text-gray-900 mb-2">搜索失败</h3>
          <p className="text-gray-600 mb-4">{error}</p>
          <button
            onClick={() => performSearch(query)}
            className="inline-flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
          >
            重试
          </button>
        </div>
      )}

      {/* 搜索结果列表 */}
      {!loading && !error && results.length > 0 && (
        <div className="space-y-6">
          {results.map((item) => (
            <article
              key={item.id}
              className="bg-white rounded-lg shadow-sm border border-gray-200 p-6 hover:shadow-md transition-shadow"
            >
              <div className="flex items-start space-x-4">
                {/* 图片 */}
                {item.imageUrl && (
                  <div className="flex-shrink-0">
                    <img
                      src={item.imageUrl}
                      alt=""
                      className="w-20 h-20 object-cover rounded-lg"
                      onError={(e) => {
                        e.target.style.display = 'none';
                      }}
                    />
                  </div>
                )}

                <div className="flex-1 min-w-0">
                  {/* 标题 */}
                  <h3 className="text-lg font-semibold text-gray-900 mb-2 line-clamp-2">
                    <a
                      href={item.url}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="hover:text-blue-600 transition-colors"
                    >
                      {highlightText(item.title, query)}
                    </a>
                  </h3>

                  {/* 描述 */}
                  {item.description && (
                    <p className="text-gray-600 mb-3 line-clamp-3">
                      {highlightText(item.description, query)}
                    </p>
                  )}

                  {/* 元信息 */}
                  <div className="flex items-center justify-between">
                    <div className="flex items-center space-x-4 text-sm text-gray-500">
                      <span>
                        {formatDistanceToNow(new Date(item.publishedAt), { 
                          addSuffix: true, 
                          locale: zhCN 
                        })}
                      </span>

                      <span>{item.source}</span>

                      <span className={`px-2 py-1 rounded-full text-xs font-medium ${getCategoryColor(item.category)}`}>
                        {item.category}
                      </span>
                    </div>

                    <a
                      href={item.url}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="text-blue-600 hover:text-blue-700 transition-colors text-sm"
                    >
                      阅读原文 →
                    </a>
                  </div>
                </div>
              </div>
            </article>
          ))}
        </div>
      )}

      {/* 空状态 */}
      {!loading && !error && hasSearched && results.length === 0 && (
        <div className="text-center py-12">
          <Search className="w-12 h-12 text-gray-400 mx-auto mb-4" />
          <h3 className="text-lg font-medium text-gray-900 mb-2">未找到相关结果</h3>
          <p className="text-gray-600 mb-4">
            试试使用不同的关键词，或搜索其他相关术语
          </p>
          <div className="text-sm text-gray-500">
            搜索建议：
            <ul className="mt-2 space-y-1">
              <li>• 使用更通用的关键词，如"AI"、"机器学习"</li>
              <li>• 尝试使用英文关键词</li>
              <li>• 检查拼写是否正确</li>
            </ul>
          </div>
        </div>
      )}

      {/* 搜索提示 */}
      {!hasSearched && (
        <div className="bg-blue-50 rounded-lg p-6">
          <h3 className="text-lg font-medium text-blue-900 mb-2">搜索提示</h3>
          <p className="text-blue-700 mb-4">
            您可以搜索以下类型的AI相关内容：
          </p>
          <div className="grid grid-cols-2 md:grid-cols-3 gap-3 text-sm">
            <div className="text-blue-600">• ChatGPT、GPT-4</div>
            <div className="text-blue-600">• PyTorch、TensorFlow</div>
            <div className="text-blue-600">• 神经网络、深度学习</div>
            <div className="text-blue-600">• 计算机视觉、NLP</div>
            <div className="text-blue-600">• 大语言模型</div>
            <div className="text-blue-600">• AI工具、框架</div>
          </div>
        </div>
      )}
    </div>
  );
};

export default SearchPage;
